const TOWNSHIP_ALIASES: Record<string, string> = {
  "north dagon": "Dagon Myothit (North)",
  "south dagon": "Dagon Myothit (South)",
  "east dagon": "Dagon Myothit (East)",
  "dagon seikkan": "Dagon Myothit (Seikkan)",
  "hlaing tharyar east": "Hlaingtharya (East)",
  "hlaing tharyar west": "Hlaingtharya (West)",
  "hlaingtharyar east": "Hlaingtharya (East)",
  "hlaingtharyar west": "Hlaingtharya (West)",
  "mingalar taung nyunt": "Mingalartaungnyunt",
  "mingala taung nyunt": "Mingalartaungnyunt",
  "mayangon": "Mayangone",
  "kamayut": "Kamaryut",
  "bota taung": "Botahtaung",
  "kyimyindaing": "Kyeemyindaing",
  "seikkan": "Dagon Myothit (Seikkan)",
};

function normalizeTownship(value: string): string {
  return value
    .normalize('NFKC')
    .toLowerCase()
    .replace(/township|မြို့နယ်/g, '')
    .replace(/[()'’.,/\-–—·]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function exactTownshipMatches(value: string): TownshipTariffRecord[] {
  const raw = String(value || '').trim();
  if (!raw) return [];
  const rawNormalized = normalizeTownship(raw);
  const aliasTarget = TOWNSHIP_ALIASES[raw.toLowerCase()] || TOWNSHIP_ALIASES[rawNormalized];
  const target = normalizeTownship(aliasTarget || raw);
  return TOWNSHIP_TARIFF_DIRECTORY.filter((row) =>
    normalizeTownship(row.township_name) === target
    || normalizeTownship(row.township_mm) === target
    || row.township_code.toLowerCase() === raw.toLowerCase(),
  );
}

export function findTownshipTariff(value: string): TownshipTariffRecord | null {
  const matches = exactTownshipMatches(value);
  return matches.length === 1 ? matches[0] : null;
}

export function findTownshipTariffByCode(code: string): TownshipTariffRecord | null {
  const normalized = String(code || '').trim().toLowerCase();
  if (!normalized) return null;
  return TOWNSHIP_TARIFF_DIRECTORY.find((row) => row.township_code.toLowerCase() === normalized) || null;
}

export function searchTownshipTariffs(query: string, limit = 40): TownshipTariffRecord[] {
  const raw = String(query || '').trim();
  const normalized = normalizeTownship(raw);
  if (!normalized) return TOWNSHIP_TARIFF_DIRECTORY.slice(0, limit);
  const tokens = normalized.split(' ').filter(Boolean);

  return TOWNSHIP_TARIFF_DIRECTORY
    .map((row, sourceIndex) => {
      const english = normalizeTownship(row.township_name);
      const myanmar = normalizeTownship(row.township_mm);
      const code = row.township_code.toLowerCase();
      const haystack = normalizeTownship([
        row.township_name,
        row.township_mm,
        row.city,
        row.region,
        row.region_mm,
        row.service_provider,
        row.township_code,
      ].join(' '));
      if (!tokens.every((token) => haystack.includes(token))) return null;

      let score = 50;
      if (code === raw.toLowerCase()) score = 0;
      else if (english === normalized || myanmar === normalized) score = 1;
      else if (english.startsWith(normalized) || myanmar.startsWith(normalized)) score = 5;
      else if (english.includes(normalized) || myanmar.includes(normalized)) score = 10;
      else if (normalizeTownship(row.city) === normalized || normalizeTownship(row.region) === normalized || normalizeTownship(row.region_mm) === normalized) score = 20;
      if (!row.source_active) score += 1000;
      return { row, score, sourceIndex };
    })
    .filter((item): item is { row: TownshipTariffRecord; score: number; sourceIndex: number } => Boolean(item))
    .sort((left, right) => left.score - right.score || left.sourceIndex - right.sourceIndex)
    .slice(0, limit)
    .map((item) => item.row);
}

export function townshipDisplayName(row: TownshipTariffRecord, language: UiLanguage, includeRegion = false): string {
  const base = language === 'my'
    ? `${row.township_mm} — ${row.township_name}`
    : `${row.township_name} — ${row.township_mm}`;
  if (!includeRegion) return base;
  const region = language === 'my' ? (row.region_mm || row.region) : row.region;
  return `${base} · ${region}`;
}
